const b = $input.first().json.body || {};
const { type, table, record = {}, old_record = {} } = b;
let event = null, caseId = null;
if (table === 'documents' && type === 'INSERT') { event = 'document'; caseId = record.case_id; }
else if (table === 'messages' && type === 'INSERT') { event = record.author === 'advisor' ? 'message_conseiller' : 'message_client'; caseId = record.case_id; }
else if (table === 'cases' && type === 'UPDATE' && record.status !== old_record.status) { event = 'statut'; caseId = record.id; }
if (!event || !caseId) return [];
return [{ json: { event, caseId, record } }];

const SITE = 'https://myvisadtv.com';
const espaceUrl = (lang) => SITE + ({ en: '/en', de: '/de' }[lang] || '') + '/dossier/';
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const first = (n) => esc(String(n || '').trim().split(/\s+/)[0] || '');
const SIGN = { fr: 'Alexandre<br>MyVisaDTV · contact@myvisadtv.com', en: 'Alexandre<br>MyVisaDTV · contact@myvisadtv.com', de: 'Alexandre<br>MyVisaDTV · contact@myvisadtv.com' };
const HELLO = { fr: 'Bonjour', en: 'Hello', de: 'Hallo' };
function bouton(href, label) {
  return `<p style="margin:28px 0"><a href="${href}" style="background:#16233f;color:#fff;padding:14px 22px;border-radius:999px;text-decoration:none;font-weight:600;display:inline-block">${label}</a></p>`;
}
function mail(lang, name, paras, cta) {
  const l = ['fr', 'en', 'de'].includes(lang) ? lang : 'fr';
  const body = paras.map((p) => `<p style="margin:0 0 14px">${p}</p>`).join('');
  const html = `<div style="font-family:-apple-system,Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.55;color:#1f2937;max-width:560px">`
    + `<p style="margin:0 0 14px">${HELLO[l]} ${first(name)},</p>${body}${cta ? bouton(cta[0], cta[1]) : ''}<p style="margin:24px 0 0">${SIGN[l]}</p></div>`;
  const text = [`${HELLO[l]} ${String(name || '').split(' ')[0]},`, ...paras.map((p) => p.replace(/<br>/g, '\n').replace(/<[^>]+>/g, '')), cta ? `${cta[1]} : ${cta[0]}` : '', 'Alexandre — MyVisaDTV'].filter(Boolean).join('\n\n');
  return { html, text };
}

const c = $input.first().json;
if (!c || !c.id) return [];
const ev = $('Analyser l\'événement').first().json;
const espace = espaceUrl(c.lang);
const out = { telegram: '', sendMail: false };
const l = ['fr', 'en', 'de'].includes(c.lang) ? c.lang : 'fr';

if (ev.event === 'document') out.telegram = `📄 ${c.client_name} a déposé « ${ev.record.file_name} ».`;
if (ev.event === 'message_client') out.telegram = `💬 Nouveau message de ${c.client_name} dans son espace : ${String(ev.record.body || '').slice(0, 300)}`;

// E-mails au client (uniquement s'il a un compte avec e-mail)
const S = {
  verification: { fr: 'Votre dossier est complet : nous le vérifions. Vous recevez votre rapport écrit sous 48 h ouvrées.', en: 'Your file is complete and we are checking it. You will get your written report within 48 business hours.', de: 'Ihre Unterlagen sind vollständig und werden geprüft. Ihren schriftlichen Bericht erhalten Sie innerhalb von 48 Werktagsstunden.' },
  rapport: { fr: 'Votre rapport de vérification est disponible dans votre espace.', en: 'Your document check report is available in your space.', de: 'Ihr Prüfbericht ist in Ihrem Bereich verfügbar.' },
  depot: { fr: 'Votre demande de visa a été déposée sur le portail officiel e-Visa.', en: 'Your visa application has been filed on the official e-Visa portal.', de: 'Ihr Visumantrag wurde im offiziellen e-Visa-Portal eingereicht.' },
  decision: { fr: 'Votre demande est en cours d’examen par les autorités thaïlandaises. Nous vous prévenons dès la décision.', en: 'Your application is being reviewed by the Thai authorities. We will let you know as soon as there is a decision.', de: 'Ihr Antrag wird von den thailändischen Behörden geprüft. Wir informieren Sie, sobald eine Entscheidung vorliegt.' },
  approuve: { fr: '🎉 Bonne nouvelle : votre visa DTV a été accordé ! Les détails sont dans votre espace.', en: '🎉 Good news: your DTV visa has been granted! Details are in your space.', de: '🎉 Gute Nachricht: Ihr DTV-Visum wurde erteilt! Details finden Sie in Ihrem Bereich.' },
  refuse: { fr: 'Votre demande a malheureusement été refusée. Nous analysons la décision et revenons vers vous très vite avec la suite, comme prévu dans nos conditions.', en: 'Unfortunately your application was refused. We are reviewing the decision and will get back to you shortly with the next steps, as set out in our terms.', de: 'Ihr Antrag wurde leider abgelehnt. Wir prüfen die Entscheidung und melden uns in Kürze mit den nächsten Schritten, wie in unseren AGB vorgesehen.' },
};
const OBJ = {
  statut: { fr: 'Votre dossier DTV avance', en: 'Your DTV file has been updated', de: 'Neuigkeiten zu Ihrem DTV-Antrag' },
  message_conseiller: { fr: 'Nouveau message de votre conseiller', en: 'New message from your advisor', de: 'Neue Nachricht von Ihrem Berater' },
};
const CTA = { fr: 'Ouvrir mon espace', en: 'Open my space', de: 'Bereich öffnen' };
let para = null;
if (ev.event === 'statut' && S[c.status]) para = S[c.status][l];
if (ev.event === 'message_conseiller') para = { fr: 'Vous avez un nouveau message de votre conseiller dans votre espace client.', en: 'You have a new message from your advisor in your client space.', de: 'Sie haben eine neue Nachricht Ihres Beraters in Ihrem Kundenbereich.' }[l];
if (para && c.email) {
  const m = mail(l, c.client_name, [para], [espace, CTA[l]]);
  Object.assign(out, { sendMail: true, to: c.email, objet: OBJ[ev.event][l], html: m.html, text: m.text });
}
if (!out.sendMail && !out.telegram) return [];
return [{ json: out }];
